@layer base {
    .flex-container.icon-flex {
        gap: 2ch;
        justify-content: flex-start;
        a {
            text-decoration: none;
        }
    }
    [data-webtui-theme='light'] {
        /* --background-active: oklch( */
        /*     from #666666 calc(l * var(--oklch-scale)) c h / 0.1 */
